def evidence(ref):
 path,prefix,symbol=ref; b=(BASE/'source'/path).read_bytes(); needle=prefix.encode(); starts=[m.start() for m in re.finditer(re.escape(needle),b) if m.start()==0 or b[m.start()-1]==10]; assert len(starts)==1,(path,prefix,starts)
 start=starts[0]; end=b.index(b'\n}',start)+2
 return dict(source_sha=SHA,path=path,symbol=symbol,start_line=b[:start].count(b'\n')+1,end_line=b[:end].count(b'\n')+1,span=dict(start=start,end=end),sha256=hashlib.sha256(b[start:end]).hexdigest())
def main():
 limit=int(sys.argv[1]) if len(sys.argv)>1 else len(SPECS); specs=SPECS[:limit]; rows=[]; gold=[]
 for s in specs:
  family='gin.v19.'+s['key']; h=hashlib.sha256(family.encode()).hexdigest(); split='holdout' if int(h,16)%4==0 else 'dev'; ev=[evidence(r) for r in s['refs']]
  answers=[] if s['no_answer'] else [dict(id=f'facet-{i+1}',primary=True,grade=3,alternatives=[dict(path=e['path'],symbol=dict(name=e['symbol'].split('.')[-1],qname=None,kind='function'),span=e['span'])]) for i,e in enumerate(ev)]
  scope=sorted(set(e['path'] for e in ev))
  ann=dict(status='candidate_not_independently_reviewed',source_sha=SHA,family_sha256=h,gold_evidence=ev,literal_answer=s['literal_answer'],chain_edges=[dict(from_facet=a+1,to_facet=b+1,relation=c) for a,b,c in s['edges']])
  if s['no_answer']: ann['absence_review']=dict(scope=scope,method='author read entirety of each scoped file; compare near-miss evidence; no retrieval rank inspection',scope_sha256={p:hashlib.sha256((BASE/'source'/p).read_bytes()).hexdigest() for p in scope},conclusion=s['literal_answer'])
  row=dict(id=family,category=s['category'],difficulty=3 if s['edges'] or s['no_answer'] else 2,language='Go',split=split,query_family=family,query=s['query'],path_prefix=scope[0] if s['no_answer'] and len(scope)==1 else None,no_answer=s['no_answer'],expected_files=[],answers=answers,annotations=ann)
  rows.append(row); gold.append(dict(family=family,**ann))
 for split in ['dev','holdout']:
  (BASE/'questions'/f'{split}.jsonl').write_text(''.join(json.dumps(q,ensure_ascii=False,separators=(',',':'))+'\n' for q in rows if q['split']==split))
 (BASE/'gold'/'evidence.json').write_text(json.dumps(gold,ensure_ascii=False,indent=2)+'\n')
 summary=dict(status='candidate_not_independently_reviewed',families=len(rows),category_counts=dict(collections.Counter(q['category'] for q in rows)),split_counts=dict(collections.Counter(q['split'] for q in rows)),split_rule='SHA256(UTF8 stable family ID) integer modulo 4 == 0: holdout; else dev; prospective 75/25, not global frozen split',family_set_sha256=hashlib.sha256('\n'.join(sorted(q['query_family'] for q in rows)).encode()).hexdigest(),question_sha256={s:hashlib.sha256((BASE/'questions'/f'{s}.jsonl').read_bytes()).hexdigest() for s in ['dev','holdout']})
 (BASE/'evidence'/'summary.json').write_text(json.dumps(summary,indent=2)+'\n'); print(json.dumps(summary))
 for split in ['dev','holdout']:
  suite=dict(schema_version=1,name='gin-v19-candidate-'+split,source=dict(root='source',commit=None,digest='',files=sorted(p.relative_to(BASE/'source').as_posix() for p in (BASE/'source').rglob('*.go'))),queries=f'questions/{split}.jsonl',queries_digest='',scoring='codecortex-native-v1',repetitions=1,warmup=0,seed=19,timeout_ms=30000,top_k=10,engine_config=dict(auto_index=dict(enabled=False)))
  (BASE/f'suite-{split}.json').write_text(json.dumps(suite,indent=2)+'\n')
if __name__=='__main__': main()
